#pragma once
#include "color_value_model.h"
#include <array>
#include <optional>
#include <vector>
#include <limits>
#include <string_view>
namespace moon {
enum class PickerMoonField {HsvSquare,HslTriangle};
inline std::string_view pickerMoonFieldKey(PickerMoonField f){return f==PickerMoonField::HslTriangle?"hsl-triangle":"hsv-square";}
inline PickerMoonField parsePickerMoonField(std::string_view text){return text=="hsl-triangle"?PickerMoonField::HslTriangle:PickerMoonField::HsvSquare;}
constexpr double pickerMoonInner=.84,pickerMoonSquare=.58,pickerMoonRotation=150,pickerMoonPi=3.14159265358979323846;
struct PickerMoonPoint {double x,y;};
struct PickerMoonWeights {double tip=1,white=0,black=0;};
inline std::array<PickerMoonPoint,3> pickerMoonVertices(){const double r=pickerMoonInner-.012;return {{{.5+r/2,.5},{.5-r/4,.5-r*std::sqrt(3.)/4},{.5-r/4,.5+r*std::sqrt(3.)/4}}};}
inline std::optional<PickerMoonWeights> pickerMoonInside(double x,double y){const auto v=pickerMoonVertices();const auto t=v[0],w=v[1],b=v[2];const double den=(w.y-b.y)*(t.x-b.x)+(b.x-w.x)*(t.y-b.y);double a=((w.y-b.y)*(x-b.x)+(b.x-w.x)*(y-b.y))/den;double c=((b.y-t.y)*(x-b.x)+(t.x-b.x)*(y-b.y))/den,d=1-a-c;constexpr double eps=1e-7;if(a< -eps||c< -eps||d< -eps)return std::nullopt;a=a<=eps?0:a;c=c<=eps?0:c;d=d<=eps?0:d;const double sum=a+c+d;return PickerMoonWeights{a/sum,c/sum,d/sum};}
inline PickerMoonWeights pickerMoonClosest(double x,double y){if(auto inside=pickerMoonInside(x,y))return *inside;const auto vertices=pickerMoonVertices();double distance=std::numeric_limits<double>::infinity();PickerMoonPoint best=vertices[0];for(int edge=0;edge<3;++edge){const auto a=vertices[edge],b=vertices[(edge+1)%3];const double dx=b.x-a.x,dy=b.y-a.y;const double amount=std::clamp(((x-a.x)*dx+(y-a.y)*dy)/(dx*dx+dy*dy),0.,1.);const PickerMoonPoint p{a.x+amount*dx,a.y+amount*dy};const double next=(x-p.x)*(x-p.x)+(y-p.y)*(y-p.y);if(next<distance){distance=next;best=p;}}return pickerMoonInside(best.x,best.y).value_or(PickerMoonWeights{});}
inline std::uint32_t pickerMoonTriangleColor(double hue,PickerMoonWeights w,int alpha=255){const double l=pickerUnit(w.white+w.tip*.5),chroma=1-std::abs(2*l-1),s=chroma>1e-7?pickerUnit(w.tip/chroma):0;return colorFromValues(ColorValueMode::Hsl,ColorValues{hue,s*100,l*100,double(alpha)},0);}
inline PickerMoonWeights pickerMoonColorWeights(std::uint32_t color){const auto hsl=colorToValues(color,ColorValueMode::Hsl);const double l=hsl[2]/100,tip=hsl[1]/100*(1-std::abs(2*l-1)),white=std::max(0.,l-tip*.5),black=std::max(0.,1-tip-white),sum=tip+white+black;return {tip/sum,white/sum,black/sum};}
inline std::pair<double,double> pickerMoonCenterMarker(PickerHsv hsv,PickerMoonField field){if(field==PickerMoonField::HsvSquare)return {(1-pickerMoonSquare)/2+hsv.s*pickerMoonSquare,(1-pickerMoonSquare)/2+(1-hsv.v)*pickerMoonSquare};const auto w=pickerMoonColorWeights(pickerHsvToRgb(hsv));const auto v=pickerMoonVertices();return {w.tip*v[0].x+w.white*v[1].x+w.black*v[2].x,w.tip*v[0].y+w.white*v[1].y+w.black*v[2].y};}
inline std::pair<double,double> pickerMoonHueMarker(double hue){const double a=(hue-pickerMoonRotation)*pickerMoonPi/180,r=(pickerMoonInner+1)/4;return {.5+std::cos(a)*r,.5+std::sin(a)*r};}
struct PickerMoonGesture {enum class Zone {None,Hue,Center};Zone zone=Zone::None;double fieldHue=0;void reset(){zone=Zone::None;}void sample(PickerRole& role,PickerMoonField field,double x,double y){x=pickerUnit(x);y=pickerUnit(y);const double dx=(x-.5)*2,dy=(y-.5)*2;if(zone==Zone::None){zone=std::hypot(dx,dy)>=pickerMoonInner?Zone::Hue:Zone::Center;fieldHue=role.hsv.h;}if(zone==Zone::Hue)role.hsv.h=pickerHue(std::atan2(dy,dx)*180/pickerMoonPi+pickerMoonRotation);else if(field==PickerMoonField::HslTriangle){role.hsv=pickerRgbToHsv(pickerMoonTriangleColor(fieldHue,pickerMoonClosest(x,y)));role.hsv.h=pickerHue(fieldHue);}else {role.hsv.s=pickerUnit((dx/pickerMoonSquare+1)/2);role.hsv.v=1-pickerUnit((dy/pickerMoonSquare+1)/2);}role.emit();}};
struct PickerMoonGeometry {int width=0,height=0;std::vector<PickerMoonWeights> weights;std::vector<unsigned char> inside;void ensure(int w,int h){if(width==w&&height==h)return;width=w;height=h;weights.resize(std::size_t(w)*h);inside.resize(weights.size());for(int y=0;y<h;++y)for(int x=0;x<w;++x){const auto i=std::size_t(y)*w+x;const double nx=double(x)/std::max(1,w-1),ny=double(y)/std::max(1,h-1);weights[i]=pickerMoonClosest(nx,ny);inside[i]=bool(pickerMoonInside(nx,ny));}}};
inline std::optional<std::uint32_t> pickerMoonCenterColor(double x,double y,double hue,PickerMoonField field,const PickerMoonWeights* cached=nullptr,bool inside=true){const double dx=(x-.5)*2,dy=(y-.5)*2,r=std::hypot(dx,dy);if(r>=pickerMoonInner&&r<=1)return std::nullopt;if(field==PickerMoonField::HslTriangle){if(!inside||(!cached&&!pickerMoonInside(x,y)))return std::nullopt;return pickerHsvToRgb(pickerRgbToHsv(pickerMoonTriangleColor(hue,cached?*cached:pickerMoonClosest(x,y))));}if(std::abs(dx)>pickerMoonSquare||std::abs(dy)>pickerMoonSquare)return std::nullopt;return pickerHsvToRgb({hue,pickerUnit((dx/pickerMoonSquare+1)/2),1-pickerUnit((dy/pickerMoonSquare+1)/2)});}
inline std::uint32_t pickerMoonRingColor(double x,double y){const double dx=(x-.5)*2,dy=(y-.5)*2,r=std::hypot(dx,dy),edge=2./512;const double coverage=pickerUnit((1-r)/edge+.5)*pickerUnit((r-pickerMoonInner)/edge+.5);if(coverage<=0)return 0;return pickerHsvToRgb({pickerHue(std::atan2(dy,dx)*180/pickerMoonPi+pickerMoonRotation),1,1},pickerByte(coverage*255));}
}
